'use strict';
/* public/js/90-loop.js -- the requestAnimationFrame main loop. Generated by scripts/split-client.mjs; see ARCHITECTURE.md. */
/* ---------- main loop ---------- */
let last=performance.now(),tAcc=0,mapT=0;
/* PERF: adaptive resolution. Every 2 seconds, check the real frame rate. Under 45 fps, render fewer pixels (down to
   0.75x the screen's resolution); after 6 smooth seconds at 57+ fps, step back up toward full. Drawing fewer pixels is
   the quickest way to get frames back on phones and older laptops. The HUD is HTML, so its text stays sharp.
   Add #fps to the page address to see the frame rate and current resolution in the corner. */
const PERF={pr:MAX_PR,frames:0,t0:0,good:0,fps:0,el:null,warned:false,logN:0};
/* Which graphics chip the browser is drawing with. If Chrome can't use the real GPU (hardware acceleration switched
   off in settings, a blocklisted driver, remote desktop), it falls back to drawing on the CPU ("SwiftShader",
   "llvmpipe"), which is roughly 10x slower. We warn the player once when that happens, because no in-game setting fixes it. */
const GPU_NAME=(()=>{try{const gl=renderer.getContext(),ext=gl.getExtension('WEBGL_debug_renderer_info');return String(ext?gl.getParameter(ext.UNMASKED_RENDERER_WEBGL):gl.getParameter(gl.RENDERER))}catch(e){return'unknown'}})();
const SOFTWARE_GPU=/swiftshader|llvmpipe|software|basic render/i.test(GPU_NAME);
/* pause menu: the element always exists now (so the Options "Show FPS" checkbox has something to toggle);
   it stays hidden unless #fps is in the address or the setting is on -- see applyFpsVisibility(). */
PERF.el=document.createElement('div');PERF.el.style.cssText='position:fixed;right:8px;bottom:8px;z-index:50;font:600 13px/1.35 monospace;white-space:pre;text-align:right;color:#fff;background:rgba(0,0,0,.55);padding:4px 6px;border-radius:3px;pointer-events:none';PERF.el.hidden=!/fps/.test(location.hash);document.body.appendChild(PERF.el);
function perfTick(now,gap){
  if(gap>1500){PERF.frames=0;PERF.t0=now;return}   // tab was hidden (the game pauses): don't count that gap
  if(!PERF.t0)PERF.t0=now;PERF.frames++;
  const span=now-PERF.t0;if(span<2000)return;
  PERF.fps=PERF.frames*1000/span;PERF.frames=0;PERF.t0=now;
  if(SETTINGS.quality==='auto'){   // fixed Low/Medium/High settings skip this adaptive step entirely (see applyQuality)
    let pr=PERF.pr;
    if(PERF.fps<45){pr=Math.max(0.75,pr-0.15);PERF.good=0}
    else if(PERF.fps>=57){if(++PERF.good>=3){pr=Math.min(MAX_PR,pr+0.15);PERF.good=0}}
    else PERF.good=0;
    if(Math.abs(pr-PERF.pr)>0.01){PERF.pr=pr;renderer.setPixelRatio(pr);renderer.setSize(innerWidth,innerHeight)}
  }
  if(PERF.el)PERF.el.textContent=`${Math.round(PERF.fps)} fps · ${PERF.pr.toFixed(2)}x · ${renderer.info.render.calls} draws · ${Math.round(renderer.info.render.triangles/1000)}k tris\nGPU: ${GPU_NAME}`;
  if(SOFTWARE_GPU&&S.started&&!PERF.warned){PERF.warned=true;toast('Your browser is drawing the game without your graphics card, so it will be slow. In Chrome: Settings > System > turn on "Use graphics acceleration when available", then restart Chrome.','bad',15000)}
  if(S.started&&++PERF.logN>=5){PERF.logN=0;logEv('perf',{fps:Math.round(PERF.fps),pr:+PERF.pr.toFixed(2),gpu:GPU_NAME,sw:SOFTWARE_GPU})}   // ~10s (perfTick fires every ~2s)
}
/* periodic "what does this client see nearby" snapshot for the play-test log: only lizards actively chasing/fleeing
   (not all 48 wandering ones — that would be pure noise), nearby D Tent bots, nearby remote players, and any
   twisters currently visible. Skipped entirely if there's nothing nearby worth a line. */
let logReportT=0;
function updateLogReport(dt){
  if(!S.started||!online())return;
  logReportT-=dt;if(logReportT>0)return;logReportT=3+Math.random();
  const liz=[];for(const L of lizards){if(L.mode==='wander')continue;if(Math.hypot(L.x-P.x,L.z-P.z)<50)liz.push([+L.x.toFixed(1),+L.z.toFixed(1),L.mode])}
  const bt=[];for(const b of bots){const g=b.p.g.position;if(Math.hypot(g.x-P.x,g.z-P.z)<40)bt.push([b.d.n,b.state,+g.x.toFixed(1),+g.z.toFixed(1)])}
  const rp=[];for(const R of remotes.values()){const g=R.p.g.position;if(Math.hypot(g.x-P.x,g.z-P.z)<40)rp.push([R.name,+g.x.toFixed(1),+g.z.toFixed(1)])}
  const tw=[];for(const tw2 of TW_LIVE.values())if(tw2.s>0.05)tw.push([+tw2.x.toFixed(1),+tw2.z.toFixed(1),+tw2.s.toFixed(2)]);
  if(liz.length||bt.length||rp.length||tw.length)logEv('report',{liz,bots:bt,rp,tw});
}
function frame(now){
  perfTick(now,now-last);
  const dt=Math.min(0.05,(now-last)/1000);last=now;tAcc+=dt;
  if(S.started){updatePlayer(dt);updateCamera(dt);updateCurfew(dt);updateCoop(dt);updateHealth(dt)}else titleCamera(dt);
  updateTwisters(dt);updateLandslides(dt);updateTumbleweeds(dt);updateVultures(dt);updateLion(dt);updateThumbHaze();updateWatchtowers();
  updateEmotes(dt);updateWalkie(dt);updateHopper(dt);updateMines(dt);updateGrab(dt);updateRoster(dt);updateBots(dt,now);updateClerk(dt);updateLizards(dt,tAcc);updateJavelinas(dt);updateParty(dt,now);updateRemotes(dt);updateTruck(dt);updateNorth(dt);updateCoords();updateCrewPanel(dt);updateRagdolls(dt);updateParts(dt);updatePops(dt);updateHoles(dt);updateRain(dt);updateDetector(dt);updateLogReport(dt);updateVoice(now);updateSinkholes(dt);updateZones(dt);
  if(S.won&&!PARTY.on){scene.fog.color.lerp(FOG_RAIN,dt*0.4)}
  updateHaboob(dt);updateMood(dt);updateTown(dt);   // updateTown: the buried town is dark (89-town.js)   // final blend on top of whatever fog/sky/light the day-night/disco/win code left this frame (see 75-haboob.js)
  updateFootsteps(dt);updateAudioScene();
  sendPresence(now);
  if(S.started){hudT-=dt;if(hudT<=0){hudT=0.1;updateHUD()}mapT-=dt;if(mapT<=0){mapT=0.2;drawMap()}}
  const fx=S.started?P.x:0,fz=S.started?P.z:12;
  streamChunks(fx,fz);farU.uFocus.value.set(fx,fz);flushTerrain();updateViewmodel();stars.position.copy(camera.position);
  sun.position.set(fx+SUN_DIR.x*80,SUN_DIR.y*80,fz+SUN_DIR.z*80);sun.target.position.set(fx,0,fz);sun.target.updateMatrixWorld();
  sky.position.copy(camera.position);
  updateGoldFx(dt);   // panning / sifting you watch (89-goldfx.js): drives the view while it runs
  renderer.render(scene,camera);
  updateLabels(now);
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
